Title: Render color in Direct X12

I’m building a small custom C++ game engine from scratch to learn how modern game engines work. I’m currently implementing the Direct3D 12 renderer on Windows.

My goal is not to copy/paste a complete engine or use an abstraction library. I want to understand the architecture and implement it myself, while still making steady progress.

Renderer.h

#pragma once
#include <d3d12.h>
#include <DirectXMath.h>
#include <d3dcompiler.h>

using namespace DirectX;
#include <wrl.h>
using namespace Microsoft::WRL;
class Window;

    class Renderer
    {
    public:
        Renderer(Window* pwindow);
        ~Renderer();
        void CreateDevice();
        void CreateSwapChain();
        void CreateRenderTarget();

        void ClearColor(XMFLOAT4 color);
        void Present();

    private:
        Window* mWindow;
        ComPtr<ID3D12Device> mDevice;
        ComPtr<ID3D12GraphicsCommandList> mDeviceContext;
        ComPtr<IDXGISwapChain> mSwapChain;
        ComPtr<ID3D12DescriptorHeap> mRenderTarget;
        D3D12_CPU_DESCRIPTOR_HANDLE m_rtvDescriptor;
    };

Renderer.cpp

#include "Renderer.h"
#include <Engine/Core/Application/Window.h>
#include <cstdio>

    Renderer::Renderer(Window* pwindow) : mWindow(pwindow), mDevice(nullptr), mSwapChain(nullptr)
    {
        CreateDevice();
        CreateSwapChain();
        CreateRenderTarget();
    }

    Renderer::~Renderer()
    {
    }

    void Renderer::CreateDevice()
    {
        D3D_FEATURE_LEVEL featureLevels[] = {
D3D_FEATURE_LEVEL_12_0
};
        if (FAILED(D3D12CreateDevice(nullptr,
D3D_FEATURE_LEVEL_12_2
, IID_PPV_ARGS(&mDevice))))
        {
            printf("Failed to create D3D12 device\n");
            abort();
        }
        else
        {
            printf("D3D12 device created\n");
        }
    }

    void Renderer::CreateSwapChain()
    {
        DXGI_SWAP_CHAIN_DESC swapChainDesc = {};
        swapChainDesc.BufferCount = 1;
        swapChainDesc.BufferDesc.Width = mWindow->GetWindowSize().x;
        swapChainDesc.BufferDesc.Height = mWindow->GetWindowSize().y;
        swapChainDesc.BufferDesc.Format =
DXGI_FORMAT_R8G8B8A8_UNORM
;
        swapChainDesc.BufferDesc.RefreshRate.Numerator = 60;
        swapChainDesc.BufferDesc.RefreshRate.Denominator = 1;
        swapChainDesc.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
        swapChainDesc.OutputWindow = mWindow->GetWindowNativeHandler();
        swapChainDesc.SampleDesc.Count = 1;
        swapChainDesc.SampleDesc.Quality = 0;
        swapChainDesc.Windowed = true;

        ComPtr<IDXGIDevice> dxgiDevice;
        mDevice.As(&dxgiDevice);
        ComPtr<IDXGIAdapter> dxgiAdapter;
        dxgiDevice->GetAdapter(dxgiAdapter.GetAddressOf());

        ComPtr<IDXGIFactory> dxgiFactory;
        dxgiFactory->GetParent(IID_PPV_ARGS(&dxgiFactory));

        if (FAILED(dxgiFactory->CreateSwapChain(mDevice.Get(), &swapChainDesc, mSwapChain.GetAddressOf())))
        {
            printf("Failed to create swap chain\n");
            abort();
        }
        else
        {
            printf("Swap chain created\n");
        }
    }

    void Renderer::CreateRenderTarget()
    {
        ComPtr<ID3D12Resource> colorBuffer;
        mSwapChain->GetBuffer(0, IID_PPV_ARGS(&colorBuffer));
        mDevice->CreateRenderTargetView(colorBuffer.Get(), nullptr, m_rtvDescriptor);
    }

    void Renderer::ClearColor(XMFLOAT4 color)
    {
        float clearColor[] = {color.x, color.y, color.z, color.w};
        mDeviceContext->ClearRenderTargetView( m_rtvDescriptor, clearColor, 0, nullptr);
    }

    void Renderer::Present()
    {
        mSwapChain->Present(1, 0);
    }

Title: Recommended workaround for the Lua(La)TeX `\mathit` regression in TeX Live 2026

Earlier this year I reported what appears to be a regression in LuaLaTeX's \mathit behaviour that was introduced in TeX Live 2026. The original discussion with the LuaTeX developers is here: https://tug.org/pipermail/luatex/2026-April/008187.html

In short, the commonly recommended practice of using \mathit{} for multi-letter identifiers produces visually displeasing results with LuaLaTeX v1.24.0 (TeX Live 2026):

\documentclass{standalone}

\begin{document}
\begin{tabular}{ll}
     \verb!|\emph{different}|!         & |\emph{different}|     \\
     \verb!|$\textit{different}$|!     & |$\textit{different}$| \\
     \verb!|$\mathit{different}$|!     & |$\mathit{different}$| \\
     \verb!|$different$|!              & |$different$|          \\
\end{tabular}
\end{document}

As far as I understand, the underlying issue has since been fixed in LuaTeX v1.25.8. However, TeX Live generally does not update the LuaTeX binary during the lifetime of a TeX Live release, so this fix is unlikely to reach most TeX Live 2026 users until the next annual release.

Assuming a user is required to use LuaLaTeX (for other reasons), what is the recommended workaround in the meantime? I would prefer not to change all occurrences of \mathit in my sources for what appears to be a temporary regression, and downgrading to TeX Live 2025 also seems like an undesirable solution.

Alternatively, is there a practical way to use a newer LuaTeX binary with an existing TeX Live 2026 installation? (I have tried to do so, but I have not managed to get it working.)

Thanks!

